void ScriptSession::bindTransportNatives(){
    bind("IsUnitLoaded","boolean",{"unit"},[this](auto& vm,auto a){return vm.boolean(alive(a[0].bits,NativeKind::Unit) && units_.at(a[0].bits)->transport!=0);});
    bind("IsUnitInTransport","boolean",{"unit","unit"},[this](auto& vm,auto a){return vm.boolean(alive(a[0].bits,NativeKind::Unit) && alive(a[1].bits,NativeKind::Unit) && units_.at(a[0].bits)->transport==a[1].bits);});
    bind("GetTransportUnit","unit",{},[this](auto& vm,auto){return vm.handle("unit",contexts_.empty()?0:contexts_.back().transportUnit);});
    bind("GetLoadedUnit","unit",{},[this](auto& vm,auto){return vm.handle("unit",contexts_.empty()?0:contexts_.back().loadedUnit);});
}
